// FrameReader 是正文抽象介面；不是 ZIP 中的 FrameParser。
byte[] readBuffer = new byte[4096];
var frameReader = new FrameReader(maxBodyLength: 1024);

while (true)
{
    int n = await socket.ReceiveAsync(
        readBuffer.AsMemory(), SocketFlags.None, connectionToken);

    if (n == 0)
    {
        frameReader.CompleteInput(); // 無殘留才是框架間的乾淨結束
        break;
    }

    foreach (byte[] body in frameReader.Feed(readBuffer.AsSpan(0, n)))
    {
        await HandleBodyAsync(body, connectionToken);
    }
}
